// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/draft-ERC20Permit.sol";

/**
 * @title LaunchToken
 * @notice 项目启动代币合约 —— 支持铸造、销毁、批量转账和限额供应
 * @dev 继承 OpenZeppelin 的 ERC20 + Burnable + Ownable + Permit 标准
 */
contract LaunchToken is ERC20, ERC20Burnable, Ownable, ERC20Permit {
    uint8 private _decimals;       // 自定义小数位数
    uint256 public maxSupply;      // 最大供应量上限
    bool public mintingFinished;   // 是否已停止铸造

    event MintingFinished();       // 铸造停止事件

    /**
     * @notice 构造函数：初始化代币基本信息
     * @param name_ 代币名称（如 "My Token"）
     * @param symbol_ 代币符号（如 "MTK"）
     * @param decimals_ 小数位数（最大 18）
     * @param initialSupply_ 初始铸造量（部署时直接给 owner）
     * @param maxSupply_ 最大供应量（铸造不可超过此值）
     * @param owner_ 合约所有者地址
     */
    constructor(
        string memory name_,
        string memory symbol_,
        uint8 decimals_,
        uint256 initialSupply_,
        uint256 maxSupply_,
        address owner_
    ) ERC20(name_, symbol_) ERC20Permit(name_) {
        require(decimals_ <= 18, "Decimals too high");
        require(maxSupply_ >= initialSupply_, "Max supply < initial");
        _decimals = decimals_;
        maxSupply = maxSupply_;
        if (initialSupply_ > 0) {
            _mint(owner_, initialSupply_);
        }
        _transferOwnership(owner_);
    }

    /**
     * @notice 返回自定义的小数位数
     */
    function decimals() public view override returns (uint8) {
        return _decimals;
    }

    /**
     * @notice 铸造新代币（仅合约所有者可调用）
     * @param to 接收地址
     * @param amount 铸造数量
     */
    function mint(address to, uint256 amount) external onlyOwner {
        require(!mintingFinished, "Minting finished");
        require(totalSupply() + amount <= maxSupply, "Exceeds max supply");
        _mint(to, amount);
    }

    /**
     * @notice 永久停止铸造功能（仅合约所有者可调用）
     * @dev 此操作不可逆
     */
    function finishMinting() external onlyOwner {
        require(!mintingFinished, "Already finished");
        mintingFinished = true;
        emit MintingFinished();
    }

    /**
     * @notice 批量转账 —— 一次性向多个地址转账
     * @param recipients 接收地址数组
     * @param amounts 对应转账金额数组
     * @return 是否成功
     */
    function batchTransfer(
        address[] calldata recipients,
        uint256[] calldata amounts
    ) external returns (bool) {
        require(recipients.length == amounts.length, "Length mismatch");
        for (uint256 i = 0; i < recipients.length; i++) {
            _transfer(msg.sender, recipients[i], amounts[i]);
        }
        return true;
    }
}

contracts/MultiSigWallet.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title MultiSigWallet
 * @notice 多签钱包合约 —— N 个所有者中需 M 个签名才能执行交易
 * @dev 支持提交交易、批准、撤销批准和执行，可接收 ETH
 */
contract MultiSigWallet {
    // ============ 事件 ============
    event Deposit(address indexed sender, uint256 amount);       // 存入 ETH
    event Submit(uint256 indexed txId);                          // 提交新交易
    event Approve(address indexed owner, uint256 indexed txId);  // 批准交易
    event Revoke(address indexed owner, uint256 indexed txId);   // 撤销批准
    event Execute(uint256 indexed txId);                         // 执行交易

    // ============ 数据结构 ============
    /**
     * @notice 交易结构体
     * @param to 目标地址
     * @param value 发送的 ETH 数量
     * @param data 调用数据（函数选择器 + 参数）
     * @param executed 是否已执行
     */
    struct Transaction {
        address to;
        uint256 value;
        bytes data;
        bool executed;
    }

    // ============ 状态变量 ============
    address[] public owners;                           // 所有者列表
    mapping(address => bool) public isOwner;           // 地址是否是所有者
    uint256 public required;                           // 执行交易所需的最少批准数

    Transaction[] public transactions;                 // 所有交易记录
    mapping(uint256 => mapping(address => bool)) public approved;  // txId => 所有者 => 是否批准

    // ============ 修饰器 ============
    modifier onlyOwner() {
        require(isOwner[msg.sender], "Not owner");
        _;
    }

    modifier txExists(uint256 _txId) {
        require(_txId < transactions.length, "Tx does not exist");
        _;
    }

    modifier notExecuted(uint256 _txId) {
        require(!transactions[_txId].executed, "Tx already executed");
        _;
    }

    modifier notApproved(uint256 _txId) {
        require(!approved[_txId][msg.sender], "Tx already approved");
        _;
    }

    /**
     * @notice 构造函数：设定所有者列表和所需批准数
     * @param _owners 所有者地址数组
     * @param _required 执行交易所需的最小签名数
     */
    constructor(address[] memory _owners, uint256 _required) {
        require(_owners.length > 0, "Owners required");
        require(
            _required > 0 && _required <= _owners.length,
            "Invalid required number"
        );

        for (uint256 i = 0; i < _owners.length; i++) {
            address owner = _owners[i];
            require(owner != address(0), "Invalid owner");
            require(!isOwner[owner], "Owner not unique");
            isOwner[owner] = true;
            owners.push(owner);
        }
        required = _required;
    }

    /** @notice 接收 ETH 时触发 Deposit 事件 */
    receive() external payable {
        emit Deposit(msg.sender, msg.value);
    }

    /**
     * @notice 提交新交易（仅所有者可调用）
     * @param _to 目标合约地址
     * @param _value 发送的 ETH 数量
     * @param _data 调用数据（如函数选择器）
     */
    function submit(
        address _to,
        uint256 _value,
        bytes calldata _data
    ) external onlyOwner {
        transactions.push(
            Transaction({to: _to, value: _value, data: _data, executed: false})
        );
        emit Submit(transactions.length - 1);
    }

    /**
     * @notice 批准某笔交易（仅所有者可调用，不可重复批准）
     * @param _txId 交易 ID
     */
    function approve(
        uint256 _txId
    ) external onlyOwner txExists(_txId) notExecuted(_txId) notApproved(_txId) {
        approved[_txId][msg.sender] = true;
        emit Approve(msg.sender, _txId);
    }

    /**
     * @notice 获取某笔交易当前的批准数量
     * @param _txId 交易 ID
     * @return count 已批准的人数
     */
    function getApprovalCount(
        uint256 _txId
    ) public view returns (uint256 count) {
        for (uint256 i = 0; i < owners.length; i++) {
            if (approved[_txId][owners[i]]) {
                count++;
            }
        }
    }

    /**
     * @notice 执行交易（达到足够批准数后任何人均可触发）
     * @param _txId 交易 ID
     */
    function execute(
        uint256 _txId
    ) external txExists(_txId) notExecuted(_txId) {
        require(getApprovalCount(_txId) >= required, "Not enough approvals");
        Transaction storage transaction = transactions[_txId];
        transaction.executed = true;
        (bool success, ) = transaction.to.call{value: transaction.value}(
            transaction.data
        );
        require(success, "Tx failed");
        emit Execute(_txId);
    }

    /**
     * @notice 撤销对某笔交易的批准（仅所有者可调用）
     * @param _txId 交易 ID
     */
    function revoke(
        uint256 _txId
    ) external onlyOwner txExists(_txId) notExecuted(_txId) {
        require(approved[_txId][msg.sender], "Tx not approved");
        approved[_txId][msg.sender] = false;
        emit Revoke(msg.sender, _txId);
    }

    // ============ 查询函数 ============
    function getOwners() external view returns (address[] memory) {
        return owners;
    }

    function getTransactionCount() external view returns (uint256) {
        return transactions.length;
    }

    /**
     * @notice 获取某笔交易的详细信息
     * @param _txId 交易 ID
     */
    function getTransaction(
        uint256 _txId
    )
        external
        view
        returns (
            address to,
            uint256 value,
            bytes memory data,
            bool executed
        )
    {
        Transaction storage t = transactions[_txId];
        return (t.to, t.value, t.data, t.executed);
    }
}

contracts/TokenVesting.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title TokenVesting
 * @notice 代币解锁（Vesting）合约 —— 按时间线性释放代币给受益人
 * @dev 支持悬崖期（cliff）、线性解锁期、可撤销计划，防重入保护
 */
contract TokenVesting is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    /**
     * @notice 每个受益人的解锁计划
     * @param totalAmount 总解锁数量
     * @param released 已释放数量
     * @param startTime 解锁开始时间戳
     * @param cliffDuration 悬崖期时长（秒），期间代币完全锁定
     * @param vestingDuration 解锁总时长（秒）
     * @param revocable 是否可撤销
     * @param revoked 是否已被撤销
     */
    struct Schedule {
        uint256 totalAmount;
        uint256 released;
        uint256 startTime;
        uint256 cliffDuration;
        uint256 vestingDuration;
        bool revocable;
        bool revoked;
    }

    IERC20 public token;                     // 要解锁的代币
    mapping(address => Schedule) public schedules;  // 受益人 => 解锁计划
    uint256 public totalAllocated;           // 已分配的总代币数量

    event ScheduleCreated(
        address indexed beneficiary,
        uint256 amount,
        uint256 startTime,
        uint256 cliffDuration,
        uint256 vestingDuration
    );
    event TokensReleased(address indexed beneficiary, uint256 amount);
    event ScheduleRevoked(address indexed beneficiary, uint256 refundAmount);

    /**
     * @notice 构造函数
     * @param tokenAddress 代币合约地址
     * @param owner_ 合约所有者地址
     */
    constructor(address tokenAddress, address owner_) {
        require(tokenAddress != address(0), "Invalid token");
        token = IERC20(tokenAddress);
        _transferOwnership(owner_);
    }

    /**
     * @notice 为受益人创建解锁计划（仅所有者可调用）
     * @param beneficiary 受益地址
     * @param amount 解锁总数量
     * @param startTime 起始时间（0 表示当前时间）
     * @param cliffDuration 悬崖期（秒）
     * @param vestingDuration 解锁总时长（秒）
     * @param revocable 是否可撤销
     */
    function createSchedule(
        address beneficiary,
        uint256 amount,
        uint256 startTime,
        uint256 cliffDuration,
        uint256 vestingDuration,
        bool revocable
    ) external onlyOwner {
        require(beneficiary != address(0), "Invalid beneficiary");
        require(schedules[beneficiary].totalAmount == 0, "Schedule exists");
        require(amount > 0, "Amount must be > 0");
        require(vestingDuration > 0, "Vesting must be > 0");
        require(cliffDuration <= vestingDuration, "Cliff > vesting");
        if (startTime == 0) startTime = block.timestamp;

        schedules[beneficiary] = Schedule({
            totalAmount: amount,
            released: 0,
            startTime: startTime,
            cliffDuration: cliffDuration,
            vestingDuration: vestingDuration,
            revocable: revocable,
            revoked: false
        });

        totalAllocated += amount;
        token.safeTransferFrom(msg.sender, address(this), amount);
        emit ScheduleCreated(
            beneficiary,
            amount,
            startTime,
            cliffDuration,
            vestingDuration
        );
    }

    /**
     * @notice 查询受益人当前可释放但尚未释放的代币数量
     * @param beneficiary 受益地址
     * @return 可释放数量
     */
    function releasable(address beneficiary) public view returns (uint256) {
        Schedule storage s = schedules[beneficiary];
        if (s.totalAmount == 0 || s.revoked) return 0;
        return vestedAmount(beneficiary) - s.released;
    }

    /**
     * @notice 计算截至当前时间已经解锁的代币数量
     * @param beneficiary 受益地址
     * @return 已解锁数量
     */
    function vestedAmount(address beneficiary) public view returns (uint256) {
        Schedule storage s = schedules[beneficiary];
        if (s.totalAmount == 0) return 0;
        if (block.timestamp < s.startTime + s.cliffDuration) return 0;
        if (block.timestamp >= s.startTime + s.vestingDuration) {
            return s.totalAmount;
        }
        uint256 elapsed = block.timestamp - s.startTime;
        return (s.totalAmount * elapsed) / s.vestingDuration;
    }

    /**
     * @notice 受益人领取已解锁的代币（任何人可为自己调用）
     */
    function release() external nonReentrant {
        uint256 amount = releasable(msg.sender);
        require(amount > 0, "No tokens to release");

        Schedule storage s = schedules[msg.sender];
        s.released += amount;
        token.safeTransfer(msg.sender, amount);
        emit TokensReleased(msg.sender, amount);
    }

    /**
     * @notice 撤销受益人的解锁计划（仅所有者可调用）
     * @param beneficiary 受益地址
     */
    function revoke(address beneficiary) external onlyOwner {
        Schedule storage s = schedules[beneficiary];
        require(s.revocable, "Not revocable");
        require(!s.revoked, "Already revoked");
        require(s.totalAmount > 0, "No schedule");

        s.revoked = true;
        uint256 vested = vestedAmount(beneficiary);
        uint256 unreleased = vested - s.released;
        uint256 refund = s.totalAmount - vested;

        if (unreleased > 0) {
            s.released += unreleased;
            token.safeTransfer(beneficiary, unreleased);
        }
        if (refund > 0) {
            token.safeTransfer(owner(), refund);
        }
        emit ScheduleRevoked(beneficiary, refund);
    }

    /**
     * @notice 紧急提现 —— 将所有代币转回所有者（仅所有者可调用）
     */
    function emergencyWithdraw() external onlyOwner {
        uint256 balance = token.balanceOf(address(this));
        require(balance > 0, "No balance");
        token.safeTransfer(owner(), balance);
    }
}

contracts/Treasury.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title Treasury
 * @notice 资金库合约 —— 按类别分配带时间锁的代币资金
 * @dev 支持多个分配类别（如 Marketing、Team、Ecosystem），每个类别有独立的释放时间
 */
contract Treasury is Ownable {
    using SafeERC20 for IERC20;

    /**
     * @notice 资金分配结构体
     * @param amount 分配总额
     * @param released 已释放数量
     * @param category 类别名称
     * @param releaseTime 解锁时间戳
     */
    struct Allocation {
        uint256 amount;
        uint256 released;
        string category;
        uint256 releaseTime;
    }

    IERC20 public token;                              // 管理的代币
    mapping(string => Allocation) public allocations;  // 类别 => 分配详情
    string[] public categories;                        // 所有类别列表
    uint256 public totalAllocated;                     // 已分配总量

    event FundAllocated(string category, uint256 amount, uint256 releaseTime);
    event FundReleased(string category, uint256 amount);
    event TokenReceived(address indexed sender, uint256 amount);

    /**
     * @notice 构造函数
     * @param tokenAddress 代币合约地址
     * @param owner_ 合约所有者地址（建议设为多签钱包）
     */
    constructor(address tokenAddress, address owner_) {
        require(tokenAddress != address(0), "Invalid token");
        token = IERC20(tokenAddress);
        _transferOwnership(owner_);
    }

    /**
     * @notice 创建新的资金分配类别（仅所有者可调用）
     * @param category 类别名称（如 "Marketing"）
     * @param amount 分配数量
     * @param releaseTime 解锁时间戳
     */
    function allocate(
        string calldata category,
        uint256 amount,
        uint256 releaseTime
    ) external onlyOwner {
        require(bytes(category).length > 0, "Empty category");
        require(amount > 0, "Amount must be > 0");
        require(allocations[category].amount == 0, "Category exists");

        uint256 balance = token.balanceOf(address(this));
        require(balance >= totalAllocated + amount, "Insufficient balance");

        allocations[category] = Allocation({
            amount: amount,
            released: 0,
            category: category,
            releaseTime: releaseTime
        });
        categories.push(category);
        totalAllocated += amount;
        emit FundAllocated(category, amount, releaseTime);
    }

    /**
     * @notice 释放某类别的资金到指定地址（仅所有者可调用）
     * @param category 类别名称
     * @param to 接收地址
     * @param amount 释放数量
     */
    function release(
        string calldata category,
        address to,
        uint256 amount
    ) external onlyOwner {
        Allocation storage a = allocations[category];
        require(a.amount > 0, "Category not found");
        require(block.timestamp >= a.releaseTime, "Not released yet");
        require(a.released + amount <= a.amount, "Exceeds allocation");

        a.released += amount;
        token.safeTransfer(to, amount);
        emit FundReleased(category, amount);
    }

    /// @notice 获取所有类别名称列表
    function getCategories()
        external
        view
        returns (string[] memory)
    {
        return categories;
    }

    /// @notice 获取某类别的分配详情
    function getAllocation(
        string calldata category
    ) external view returns (Allocation memory) {
        return allocations[category];
    }

    /// @notice 查询合约中未分配的可用余额
    function availableBalance() external view returns (uint256) {
        return token.balanceOf(address(this)) - totalAllocated;
    }

    /**
     * @notice 紧急提现 —— 将指定数量代币转出
     * @param to 接收地址
     * @param amount 转出数量
     */
    function emergencyWithdraw(
        address to,
        uint256 amount
    ) external onlyOwner {
        token.safeTransfer(to, amount);
    }

    /// @notice 向资金库转入代币
    function receiveTokens(uint256 amount) external {
        token.safeTransferFrom(msg.sender, address(this), amount);
        emit TokenReceived(msg.sender, amount);
    }
}

